config.transformExpression:
function randomExponential(lambda) {
  return -Math.log(1 - Math.random()) / lambda;
}

// id and altPathNumber
let id = state.pipeline.get("lastId", 0);

// if id == 0
if (id <= 0)
{
  state.pipeline.set("lastId", id);
  state.pipeline.set("altPathNumber", 0);
}
let altPathNumber = state.pipeline.get("altPathNumber");
id++;
if (id >= 780)
{
  id = 1
  let altPathProb = Math.random();
  altPathNumber = 0
  if (altPathProb >= 0.8) 
  {
    altPathNumber = 2
  }
  else if (altPathProb >= 0.5)
  {
    altPathNumber = 1
  }
  state.pipeline.set("altPathNumber", altPathNumber);
}
stage.setMetadata("altPathNumber", altPathNumber);
stage.setMetadata("id", id);
// battery
let battery = state.pipeline.get("battery", 100);
battery = battery - randomExponential(1)
if (battery < 1)
{
  battery = 100
}
stage.setMetadata("battery", battery);
state.pipeline.set("battery", battery);
// login
stage.setMetadata("login", "AMR1");
stage.setValue(event.value);

